import { readFileSync } from "node:fs";
import { afterAll, describe, expect, it } from "vitest";
import { Miniflare, convertV4MiniflareOptions } from "miniflare";

// Demo story seeds (seed/story-scenarios.sql, generated by tools/story_seed_sql.py): two SYNTHETIC
// projects remixed from the persona-generator answer sets. A = Church lens high / Translation Team lens low,
// weakness "no documented translation brief" (TR-Q1) with a placeholder next-step link; B = the reverse.
// Lenses are the product's: each template's perspective from migration 0004 (what the report groups by).
const mf=new Miniflare(convertV4MiniflareOptions({workers:[{name:"storyseed",modules:true,script:"export default { fetch() { return new Response('ok') } }",d1Databases:{DB:"storyseed-test-db"}}]}));
afterAll(()=>mf.dispose());
function statements(db:D1Database,path:string) {
  const sql=readFileSync(new URL(path,import.meta.url),"utf8").split("\n").filter(l=>!l.trimStart().startsWith("--")).join("\n");
  return sql.split(";\n").map(s=>s.trim()).filter(Boolean).map(s=>db.prepare(s));
}
type Row={assessment_id:string;perspective:string;items_json:string;answers_json:string;provenance_json:string;source:string};

describe("demo story seeds: two clearly-synthetic projects whose lenses disagree",()=>{
  it("load idempotently, stay synthetic, and carry the intended split",async()=>{
    const db=await mf.getD1Database("DB");
    for(const m of ["0001_init.sql","0002_code_escrow.sql","0003_language_archive.sql","0004_pinned_instruments.sql"]) await db.batch(statements(db,`../migrations/${m}`));
    await db.batch(statements(db,"../seed/synthetic.sql"));
    await db.batch(statements(db,"../seed/story-scenarios.sql"));
    await db.batch(statements(db,"../seed/story-scenarios.sql")); // second run is a no-op
    const n=async(sql:string)=>(await db.prepare(sql).first<{n:number}>())!.n;
    expect(await n("SELECT COUNT(*) AS n FROM project WHERE id LIKE 'proj_story_%'")).toBe(2);
    expect(await n("SELECT COUNT(*) AS n FROM assessment WHERE id LIKE 'assess_story_%'")).toBe(2);
    expect(await n("SELECT COUNT(*) AS n FROM response WHERE id LIKE 'resp_story_%'")).toBe(12);
    // provenance: every story row is source='synthetic', named SYNTHETIC, invented language code
    expect(await n("SELECT COUNT(*) AS n FROM response WHERE id LIKE 'resp_story_%' AND source<>'synthetic'")).toBe(0);
    expect(await n("SELECT COUNT(*) AS n FROM project WHERE id LIKE 'proj_story_%' AND name NOT LIKE '%(SYNTHETIC)'")).toBe(0);
    expect(await n("SELECT COUNT(*) AS n FROM language WHERE id LIKE 'lang_story_%' AND (code<>'qaa' OR name NOT LIKE '%synthetic%')")).toBe(0);
    expect(await n("SELECT COUNT(*) AS n FROM assessment a LEFT JOIN \"grant\" g ON g.scope_type='assessment' AND g.scope_id=a.id AND g.principal_id='person_mara' WHERE a.id LIKE 'assess_story_%' AND g.id IS NULL")).toBe(0);

    const rows=(await db.prepare("SELECT s.assessment_id, t.perspective, t.items_json, r.answers_json, r.provenance_json, r.source FROM response r JOIN assessment_survey s ON s.id=r.assessment_survey_id JOIN survey_template t ON t.id=r.template_id AND t.version=r.template_version WHERE r.id LIKE 'resp_story_%'").all<Row>()).results;
    for(const r of rows){ const p=JSON.parse(r.provenance_json); expect(p.synthetic).toBe(true); expect(p.remixed_from).toBeTruthy(); }
    // mean source_score of scored single-choice answers, per story and per product lens (survey_template.perspective)
    const mean=(aid:string,lens:string)=>{ let sum=0,k=0; for(const r of rows.filter(r=>r.assessment_id===aid&&r.perspective===lens)){ const items=new Map((JSON.parse(r.items_json) as any[]).map(i=>[i.id,i]));
      for(const [id,v] of Object.entries(JSON.parse(r.answers_json))){ const it=items.get(id); if(it?.type!=="single") continue; const sc=it.options.find((o:any)=>o.code===v)?.source_score; if(sc==null) continue; sum+=sc; k++; } } return sum/k; };
    const A="assess_story_church-high-team-low", B="assess_story_team-high-church-low";
    expect(new Set(rows.map(r=>r.perspective))).toEqual(new Set(["Church","Translation Team"]));
    expect(mean(A,"Church")).toBeGreaterThanOrEqual(mean(A,"Translation Team")+30);
    expect(mean(B,"Translation Team")).toBeGreaterThanOrEqual(mean(B,"Church")+30);
    // A's highlighted weakness: no translation brief on every team response, with a placeholder next step
    const teamA=rows.filter(r=>r.assessment_id===A&&r.perspective==="Translation Team");
    expect(teamA.length).toBeGreaterThan(0);
    for(const r of teamA) expect(JSON.parse(r.answers_json)["TR-Q1"]).toBe("working-on");
    const notes=(await db.prepare("SELECT id, notes_next_steps FROM assessment WHERE id LIKE 'assess_story_%' ORDER BY id").all<{id:string;notes_next_steps:string|null}>()).results;
    expect(notes.find(x=>x.id===A)!.notes_next_steps).toMatch(/translation brief.*PLACEHOLDER/s);
    expect(notes.find(x=>x.id===B)!.notes_next_steps).toBeNull();
    // answers stay valid option codes of their template items
    for(const r of rows){ const items=new Map((JSON.parse(r.items_json) as any[]).map(i=>[i.id,i]));
      for(const [id,v] of Object.entries(JSON.parse(r.answers_json))){ const it=items.get(id); expect(it,`unknown item ${id}`).toBeDefined();
        if(v===null){ expect(it.required).toBe(false); continue; }
        if(it.type==="single") expect(it.options.some((o:any)=>o.code===v),`${id}=${v}`).toBe(true);
        else if(it.type==="multi") for(const c of v as string[]) expect(it.options.some((o:any)=>o.code===c),`${id}∋${c}`).toBe(true); } }
  },60_000);
});
